import type { Book, BookStatus } from '../../types';

export const STATUS_LABELS: Record<BookStatus, string> = {
  'to-read': 'To Read',
  reading: 'Reading',
  read: 'Read',
  dnf: 'Did Not Finish',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: BookStatus): string {
  switch (status) {
    case 'reading': return 'status-reading';
    case 'read': return 'status-read';
    case 'dnf': return 'status-dnf';
    default: return 'status-to-read';
  }
}

const STATUS_ORDER: BookStatus[] = ['reading', 'to-read', 'read', 'dnf'];

type StatusListProps = {
  // null = loading; array = loaded
  items: Book[] | null;
};

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul>
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="skeleton-card" />
        ))}
      </ul>
    );
  }

  const grouped = STATUS_ORDER.reduce<Record<BookStatus, Book[]>>(
    (acc, status) => {
      acc[status] = items.filter((b) => b.status === status);
      return acc;
    },
    { 'to-read': [], reading: [], read: [], dnf: [] },
  );

  return (
    <div>
      {STATUS_ORDER.map((status) => {
        const group = grouped[status];
        if (group.length === 0) return null;
        return (
          <section key={status}>
            <h2>{STATUS_LABELS[status]}</h2>
            <ul>
              {group.map((book) => (
                <li key={book.id} className={statusColor(book.status)}>
                  <span>{book.title}</span>
                  <span>{book.author}</span>
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

