import { useState } from 'react';

type ChipLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const CHIPS: ChipLabel[] = ['All', 'Active', 'Archived', 'Starred'];

const css = `
@layer components {
  .chip-filter {
    display: flex;
    gap: var(--shelf-space-sm);
    flex-wrap: wrap;
  }

  .chip-filter-button {
    --shelf-chip-bg: var(--shelf-bgColor-raised);
    --shelf-chip-fg: var(--shelf-fgColor-default);
    --shelf-chip-border: var(--shelf-borderColor-default);

    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-md);
    border-radius: var(--shelf-radius-full);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-chip-border);
    background-color: var(--shelf-chip-bg);
    color: var(--shelf-chip-fg);
    font-family: var(--shelf-font-family-base);
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-medium);
    cursor: pointer;
  }

  .chip-filter-button:hover {
    --shelf-chip-bg: var(--shelf-bgColor-accent-hover);
    --shelf-chip-fg: var(--shelf-fgColor-on-accent);
    --shelf-chip-border: var(--shelf-bgColor-accent-hover);
  }

  .chip-filter-button:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }

  .chip-filter-button:active {
    --shelf-chip-bg: var(--shelf-bgColor-accent-active);
    --shelf-chip-fg: var(--shelf-fgColor-on-accent);
    --shelf-chip-border: var(--shelf-bgColor-accent-active);
  }

  .chip-filter-button[aria-pressed="true"] {
    --shelf-chip-bg: var(--shelf-bgColor-accent);
    --shelf-chip-fg: var(--shelf-fgColor-on-accent);
    --shelf-chip-border: var(--shelf-bgColor-accent);
  }
}
`;

export function ChipFilter(): JSX.Element {
  const [active, setActive] = useState<ChipLabel>('All');

  return (
    <>
      <style>{css}</style>
      <div className="chip-filter" role="group">
        {CHIPS.map((chip) => (
          <button
            key={chip}
            type="button"
            className="chip-filter-button"
            aria-pressed={active === chip}
            onClick={() => setActive(chip)}
          >
            {chip}
          </button>
        ))}
      </div>
    </>
  );
}

