import { useEffect, useState } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';

const SKELETON_COUNT = 4;

export function TaskBoard(): JSX.Element {
  // null = loading; array (possibly empty) = loaded
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  const count = tasks !== null ? tasks.length : 0;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h2 className="task-board-heading">Tasks</h2>
        {tasks !== null && (
          <span className="task-board-count" aria-label={`${count} tasks`}>
            {count}
          </span>
        )}
      </header>

      <div className="task-board-filter-bar" />

      <ul className="task-board-list" role="list">
        {tasks === null
          ? Array.from({ length: SKELETON_COUNT }, (_, i) => (
              <li key={i} className="task-board-item task-board-item-skeleton">
                <span className="task-board-skeleton-title" />
              </li>
            ))
          : tasks.length === 0
          ? (
              <li className="task-board-empty">No tasks yet.</li>
            )
          : tasks.map((task) => (
              <li key={task.id} className="task-board-item">
                <span className="task-board-item-title">{task.title}</span>
                <span className={`task-board-item-status task-board-item-status-${task.status}`}>
                  {task.status}
                </span>
              </li>
            ))}
      </ul>
    </div>
  );
}

