import './PriceDisplay.css';

type PriceDisplayProps = {
  price: number;
  originalPrice?: number;
};

function formatPrice(cents: number): string {
  // Math.ceil avoids under-charging: business rule requires always rounding up to the next cent
  const rounded = Math.ceil(cents) / 100;
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(rounded);
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): JSX.Element {
  const isDiscounted = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span className="price-display-current">{formatPrice(price)}</span>
      {isDiscounted && (
        <span className="price-display-original">{formatPrice(originalPrice)}</span>
      )}
    </span>
  );
}
